(()=>{'use strict';if(["/bar-accessories/", "/led-light-up-cups/", "/custom-silicone-cups/", "/custom-shot-glasses/"].includes(location.pathname))return;const all={"/custom-ice-buckets/": {"title": "Custom Ice Buckets: Logo Printing for Bars & Events", "h1": "Custom Ice Buckets with Your Brand Artwork", "lead": "We make custom ice buckets with heat-transfer artwork for bars, bottle service and branded events. Choose an LED or non-LED bucket and send your logo or idea. Our factory team provides free design, a visual mockup, sampling and bulk production.", "description": "Custom ice buckets with screen-printed or heat transfer artwork for bars and events. Get a free design proposal and a product mockup from our factory team.", "heading": "Choose the bucket before the branding", "intro": "Start with the service setup and the bottle you plan to use. Capacity alone does not confirm bottle fit or how much room remains for ice.", "rows": [["Size & bottle fit", "Send bottle dimensions, the intended bottle count and any space limit. Confirm fit on the selected model rather than assuming a bottle count from litres."], ["LED or non-LED", "Compare the listed model groups. For an LED bucket, confirm the light effect, power arrangement and care instructions for that model."], ["Logo & appearance", "Share artwork, logo placement and a colour reference. Review the usable print area and decoration method for the chosen material."], ["Packing & delivery", "State the order quantity, pack contents, destination and required arrival date. MOQ and timing are confirmed in your quotation."]], "cta": "Request an Ice Bucket Quote", "href": "/contact/#models=Custom%20ice%20buckets", "related": [["#led-ice-buckets", "Compare LED models"], ["#non-led-ice-buckets", "Compare non-LED models"], ["/customization/", "Logo & decoration"], ["/packaging/", "Packaging requirements"]], "faq": [["Can I order custom printed ice buckets without LED lighting?", "Use the non-LED model group to shortlist a bucket, then share the quantity and artwork. Decoration options are reviewed for the selected model and material."], ["What should I send for an ice bucket quotation?", "Include your model shortlist or intended use, bottle dimensions, quantity, logo artwork, packaging requirements, destination and arrival date. If you need help choosing, describe the service setup."]], "html": "<section class=\"boom-buyer-brief\" id=\"buyer-brief\" aria-labelledby=\"buyer-brief-heading\"><p class=\"boom-buyer-eyebrow\">MODEL / ARTWORK / PROJECT QUOTE</p><h2 id=\"buyer-brief-heading\">Choose the bucket before the branding</h2><p>Start with the service setup and the bottle you plan to use. Capacity alone does not confirm bottle fit or how much room remains for ice.</p><dl><div><dt>Size &amp; bottle fit</dt><dd>Send bottle dimensions, the intended bottle count and any space limit. Confirm fit on the selected model rather than assuming a bottle count from litres.</dd></div><div><dt>LED or non-LED</dt><dd>Compare the listed model groups. For an LED bucket, confirm the light effect, power arrangement and care instructions for that model.</dd></div><div><dt>Logo &amp; appearance</dt><dd>Share artwork, logo placement and a colour reference. Review the usable print area and decoration method for the chosen material.</dd></div><div><dt>Packing &amp; delivery</dt><dd>State the order quantity, pack contents, destination and required arrival date. MOQ and timing are confirmed in your quotation.</dd></div></dl><a class=\"boom-buyer-cta\" href=\"/contact/#models=Custom%20ice%20buckets\">Request an Ice Bucket Quote <span aria-hidden=\"true\">↗</span></a><nav aria-label=\"Related product planning\"><a href=\"#led-ice-buckets\">Compare LED models</a><a href=\"#non-led-ice-buckets\">Compare non-LED models</a><a href=\"/customization/\">Logo &amp; decoration</a><a href=\"/packaging/\">Packaging requirements</a></nav><div class=\"boom-buyer-faq\"><h3>Before you request a quote</h3><details><summary>Can I order custom printed ice buckets without LED lighting?</summary><p>Use the non-LED model group to shortlist a bucket, then share the quantity and artwork. Decoration options are reviewed for the selected model and material.</p></details><details><summary>What should I send for an ice bucket quotation?</summary><p>Include your model shortlist or intended use, bottle dimensions, quantity, logo artwork, packaging requirements, destination and arrival date. If you need help choosing, describe the service setup.</p></details></div></section>"}, "/custom-silicone-cups/": {"title": "Custom Silicone Cups with Logo for Events & Brand Projects", "h1": "Custom Silicone Cups Designed for Your Brand", "lead": "We make custom silicone cups with UV-printed artwork and colour-changing designs for branded events and promotions. Send your logo or idea. We provide free design and a visual mockup, then develop the sample and produce your order through one factory team.", "description": "Custom silicone cups with UV printing or color changing ink for events and brand projects. Send your logo or idea for free design and a product mockup.", "heading": "Build a silicone cup brief around the use", "intro": "The cup structure, intended drink and packing method all affect the specification. Use the listed models as a starting point and confirm the details for your project.", "rows": [["Structure & size", "Shortlist a cup or collapsible design. State the required capacity, size limits and whether a lid or other component is needed."], ["Use & care", "Describe the intended drink, use setting and cleaning method. Request the applicable material information and care limits for the selected model."], ["Colour & logo", "Provide a colour reference, artwork and preferred logo location. Confirm the available decoration route and approve a project sample."], ["Existing model or new shape", "For an existing model, include its reference. For a new design, send dimensions, drawings or a physical reference for a separate feasibility review."]], "cta": "Request a Silicone Cup Quote", "href": "/contact/#models=Custom%20silicone%20cups", "related": [["#silicone-pint-cups", "Browse silicone cups"], ["#collapsible-cups", "Browse collapsible designs"], ["/customization/", "Customisation options"], ["/product-development/", "New product development"]], "faq": [["Can I customise an existing silicone cup model?", "Shortlist a model and send your logo, colour reference, quantity and packaging brief. Available changes and sample requirements are confirmed for that model."], ["Are all silicone cups suitable for the same drinks and cleaning methods?", "Do not assume the same limits for every model. Describe your drink and cleaning method and request the applicable material and care information before ordering."]], "html": "<section class=\"boom-buyer-brief\" id=\"buyer-brief\" aria-labelledby=\"buyer-brief-heading\"><p class=\"boom-buyer-eyebrow\">MODEL / ARTWORK / PROJECT QUOTE</p><h2 id=\"buyer-brief-heading\">Build a silicone cup brief around the use</h2><p>The cup structure, intended drink and packing method all affect the specification. Use the listed models as a starting point and confirm the details for your project.</p><dl><div><dt>Structure &amp; size</dt><dd>Shortlist a cup or collapsible design. State the required capacity, size limits and whether a lid or other component is needed.</dd></div><div><dt>Use &amp; care</dt><dd>Describe the intended drink, use setting and cleaning method. Request the applicable material information and care limits for the selected model.</dd></div><div><dt>Colour &amp; logo</dt><dd>Provide a colour reference, artwork and preferred logo location. Confirm the available decoration route and approve a project sample.</dd></div><div><dt>Existing model or new shape</dt><dd>For an existing model, include its reference. For a new design, send dimensions, drawings or a physical reference for a separate feasibility review.</dd></div></dl><a class=\"boom-buyer-cta\" href=\"/contact/#models=Custom%20silicone%20cups\">Request a Silicone Cup Quote <span aria-hidden=\"true\">↗</span></a><nav aria-label=\"Related product planning\"><a href=\"#silicone-pint-cups\">Browse silicone cups</a><a href=\"#collapsible-cups\">Browse collapsible designs</a><a href=\"/customization/\">Customisation options</a><a href=\"/product-development/\">New product development</a></nav><div class=\"boom-buyer-faq\"><h3>Before you request a quote</h3><details><summary>Can I customise an existing silicone cup model?</summary><p>Shortlist a model and send your logo, colour reference, quantity and packaging brief. Available changes and sample requirements are confirmed for that model.</p></details><details><summary>Are all silicone cups suitable for the same drinks and cleaning methods?</summary><p>Do not assume the same limits for every model. Describe your drink and cleaning method and request the applicable material and care information before ordering.</p></details></div></section>"}, "/products/custom-plastic-shot-glasses/": {"title": "Custom Plastic Shot Glasses: Logo & Bulk Packing | BOOM", "h1": "Custom Plastic Shot Glasses: Create Your Signature Look", "lead": "Your signature drink deserves a cup that belongs to your brand. Create custom plastic drinkware for cocktails at a launch, beer at a team event or branded drinks across your venues.", "description": "Make custom plastic shot glasses part of your brand experience. Bring your colours, logo and artwork into a coordinated project with BOOM.", "heading": "From a branded shot glass to a clear enquiry", "intro": "This page is for selecting and customising plastic shot glasses. For a new shape or a tooling-led project, use the dedicated Shot Glass OEM & ODM page.", "rows": [["Capacity & fit", "Specify the pour in ml or oz, plus any height, tray or rack restriction. Confirm the model dimensions before approving the sample."], ["Logo & finish", "Send vector artwork, a colour reference and the intended print position. Confirm the method and usable print area on the selected part."], ["Material & use", "Describe whether the glasses are for tasting, bar service or a promotional set. Ask for the material and care information applicable to the model."], ["Bulk packing or a set", "State the quantity, pack contents, destination and arrival date. Share any sleeve, box, insert or labelling requirements for review."]], "cta": "Send a Shot Glass Enquiry", "href": "#rfq", "related": [["/custom-shot-glasses/", "Compare plastic & silicone shot glasses"], ["/custom-shot-glass-oem-odm/", "New molds: Shot Glass OEM & ODM"], ["/screen-printing/", "Screen printing"], ["/packaging/", "Packaging requirements"]], "faq": [["Do I need a new mold to add a logo?", "Start by reviewing an existing model. A logo-only brief is different from changing the shape or capacity; the available decoration and any tooling requirement are confirmed during review."], ["How do I request a bulk quotation?", "Use the enquiry form with your quantity, intended pour, artwork, packaging brief and destination. If a field is undecided, describe the use so the project can be reviewed."]], "html": "<section class=\"boom-buyer-brief\" id=\"buyer-brief\" aria-labelledby=\"buyer-brief-heading\"><p class=\"boom-buyer-eyebrow\">MODEL / ARTWORK / PROJECT QUOTE</p><h2 id=\"buyer-brief-heading\">From a branded shot glass to a clear enquiry</h2><p>This page is for selecting and customising plastic shot glasses. For a new shape or a tooling-led project, use the dedicated Shot Glass OEM &amp; ODM page.</p><dl><div><dt>Capacity &amp; fit</dt><dd>Specify the pour in ml or oz, plus any height, tray or rack restriction. Confirm the model dimensions before approving the sample.</dd></div><div><dt>Logo &amp; finish</dt><dd>Send vector artwork, a colour reference and the intended print position. Confirm the method and usable print area on the selected part.</dd></div><div><dt>Material &amp; use</dt><dd>Describe whether the glasses are for tasting, bar service or a promotional set. Ask for the material and care information applicable to the model.</dd></div><div><dt>Bulk packing or a set</dt><dd>State the quantity, pack contents, destination and arrival date. Share any sleeve, box, insert or labelling requirements for review.</dd></div></dl><a class=\"boom-buyer-cta\" href=\"#rfq\">Send a Shot Glass Enquiry <span aria-hidden=\"true\">↗</span></a><nav aria-label=\"Related product planning\"><a href=\"/custom-shot-glasses/\">Compare plastic &amp; silicone shot glasses</a><a href=\"/custom-shot-glass-oem-odm/\">New molds: Shot Glass OEM &amp; ODM</a><a href=\"/screen-printing/\">Screen printing</a><a href=\"/packaging/\">Packaging requirements</a></nav><div class=\"boom-buyer-faq\"><h3>Before you request a quote</h3><details><summary>Do I need a new mold to add a logo?</summary><p>Start by reviewing an existing model. A logo-only brief is different from changing the shape or capacity; the available decoration and any tooling requirement are confirmed during review.</p></details><details><summary>How do I request a bulk quotation?</summary><p>Use the enquiry form with your quantity, intended pour, artwork, packaging brief and destination. If a field is undecided, describe the use so the project can be reviewed.</p></details></div></section>"}};let scheduled=false;function apply(){scheduled=false;const c=all[location.pathname];if(!c)return;if(document.title!==c.title)document.title=c.title;const description=document.querySelector('meta[name="description"]');if(description&&description.content!==c.description)description.content=c.description;document.querySelectorAll('meta[property="og:title"],meta[name="twitter:title"]').forEach(n=>{if(n.content!==c.title)n.content=c.title;});document.querySelectorAll('meta[property="og:description"],meta[name="twitter:description"]').forEach(n=>{if(n.content!==c.description)n.content=c.description;});const h=document.querySelector('main h1');if(h&&h.textContent!==c.h1)h.textContent=c.h1;const hero=document.querySelector('.bx-collection-hero,.ec-library-hero,.sg-hero');if(hero){const lead=hero.querySelector('.sg-lead,.ec-library-lead')||(h&&h.nextElementSibling?.tagName==='P'?h.nextElementSibling:null);if(lead&&lead.textContent!==c.lead)lead.textContent=c.lead;}if(location.pathname==='/custom-silicone-cups/'){const edits={"Silicone gets specified for one reason — it survives the places glass does not. Pick the venue first and the shortlist narrows to the moulds that already ship there.":"Start with the venue, drink and handling requirements. Then compare the listed cup structures and confirm the specification for your project.","No glass on sand, no broken stem in the cooler. Drop it on pool tile and it comes back in one piece.":"Check the venue rules, required cup size and handling conditions. Confirm the selected model and care instructions before ordering.","Wide base, no clink on fibreglass, nothing that rolls off a table once the boat is under way.":"Share the storage, table and cup-holder dimensions. Review the base shape and handling requirements for the selected model.","Folds flat — 500 units store where 100 rigid cups would. The reason event crews keep them year after year.":"Compare the folded dimensions, capacity and packing arrangement of the selected collapsible model."};document.querySelectorAll('main p').forEach(n=>{const next=edits[n.textContent.trim()];if(next)n.textContent=next;});}const main=document.querySelector('main');if(main&&!main.querySelector('#buyer-brief')){const node=document.createElement('div');node.innerHTML=c.html;const before=main.querySelector('#specs,.bx-faq-restore,.ec-library-faq');if(before)before.before(node.firstElementChild);else main.append(node.firstElementChild);}document.querySelectorAll('script[type="application/ld+json"]').forEach(n=>{try{const x=JSON.parse(n.textContent);let changed=false;function walk(o){if(!o||typeof o!=='object')return;const t=[].concat(o['@type']||[]);if(t.some(v=>['WebPage','CollectionPage'].includes(v))&&String(o.url||o['@id']||'').split('#')[0]==='https://www.boomdrinkware.com'+location.pathname){if(o.name!==c.h1||o.description!==c.description){o.name=c.h1;o.description=c.description;changed=true;}}Object.values(o).forEach(v=>Array.isArray(v)?v.forEach(walk):walk(v));}walk(x);if(changed)n.textContent=JSON.stringify(x);}catch{}});}new MutationObserver(()=>{if(!scheduled){scheduled=true;setTimeout(apply,80);}}).observe(document.documentElement,{childList:true,subtree:true});apply();window.addEventListener('popstate',apply);[400,1400,3200].forEach(t=>setTimeout(apply,t));})();